export const STREAM_VOICE_CALL=0,STREAM_SYSTEM=1,STREAM_RING=2,STREAM_MUSIC=3,STREAM_NOTIFICATION=5,STREAM_ACCESSIBILITY=10,DYNAMIC_STREAM_BROADCAST=99,DYNAMIC_STREAM_REMOTE_START_INDEX=100;export class StreamsSorter{static priorityPredicates(r){return[t=>t.isActive,t=>t.stream===3,t=>t.stream===10,t=>t.stream===2,t=>t.stream===5,t=>t.stream===0,t=>t.stream===1,t=>t.isDynamic]}static getPriority(r){const t=StreamsSorter.priorityPredicates(r).findIndex(i=>i(r));return t>=0?t:r.stream}compare(r,t){return StreamsSorter.getPriority(r)-StreamsSorter.getPriority(t)}static sort(r){return[...r].sort((t,i)=>StreamsSorter.getPriority(t)-StreamsSorter.getPriority(i))}}export function toSliderType(e){return e.stream===99?"AudioSharingStream":e.stream>=100?"RemoteMediaStream":"Stream"}export function shouldShowSliders(e,r=!1){return e.isActive?!0:e.stream===10?r:e.stream===99?!0:e.stream===3||!!e.isDynamic}export function buildSlidersModel(e,{shouldShowA11ySlider:r=!1,prevSliderTypes:t=[]}={}){const i=e.filter(s=>shouldShowSliders(s,r)),A=StreamsSorter.sort(i).map(s=>`${toSliderType(s)}:${s.stream}`),n=[...new Set([...A,...t])],o=n[0]||null,S=n.slice(1);return{slider:o,floatingSliders:S,sliderTypes:n}}export const makeStreamModel=({streamId:e,stream:r,isActive:t=!1,isDynamic:i=!1})=>({streamId:e,stream:r,isActive:t,isDynamic:i});
